      gsIntro: 'Επιλέξτε πόσους ομίλους θα έχει: οι ομάδες μοιράζονται φιδωτά με βάση την κατάταξη. Μπορείτε να αλλάξετε το μέγεθος κάθε ομίλου (3, 4 ή 5 ομάδες) και, για τους ομίλους των 4, το σύστημα.',
