      gsLegend: 'Επισημαίνονται οι ομάδες που περνούν στο Gold (προσωρινά μέχρι το τέλος των ομίλων): πρώτα οι 1ες, μετά οι 2ες, μετά οι καλύτερες με βάση το πηλίκο πόντων. Οι άλλες παίζουν στο Silver. Σειρά και bye στα ταμπλό: πρώτα οι 1ες, μετά οι 2ες κ.λπ.· μεταξύ ομάδων της ίδιας θέσης μετρούν οι βαθμοί (2 νίκη, 1 ήττα· στους ομίλους FIVB η διαδρομή νικητών/ηττημένων), μετά το πηλίκο πόντων.',
      assignHelpGs: 'Ταμπλό Gold 16 θέσεων: σειρά με βάση τη θέση στον όμιλο (πρώτα οι 1ες, μετά οι 2ες…), μετά τους βαθμούς, μετά το πηλίκο πόντων. Τα {b} bye πηγαίνουν στις καλύτερες 1ες, μετά στις καλύτερες 2ες. Ομάδες του ίδιου ομίλου δεν συναντιούνται ποτέ στους δύο πρώτους γύρους. Μπορείτε να τις αλλάξετε εδώ. Το Silver συμπληρώνεται αυτόματα με τους ίδιους κανόνες.',
